const upsertMediaReplica = `-- name: UpsertMediaReplica :one

INSERT INTO media_replica (object_id, provider_id, status, error, replicated_at)
VALUES (
    $1, $2, $3, $4,
    CASE WHEN $3::text = 'ready' THEN now() ELSE NULL END
)
ON CONFLICT (object_id, provider_id) DO UPDATE
SET status        = EXCLUDED.status,
    error         = EXCLUDED.error,
    replicated_at = CASE WHEN EXCLUDED.status = 'ready' THEN now() ELSE media_replica.replicated_at END,
    updated_at    = now()
RETURNING object_id, provider_id, status, error, replicated_at, created_at, updated_at
`

type UpsertMediaReplicaParams struct {
	ObjectID   int64
	ProviderID int64
	Status     string
	Error      string
}

// ---------- 媒体副本（S1-6f，docs/12 第 5 节） ----------
// 记录一个副本；已存在时更新状态（复制重试会重复写入）
func (q *Queries) UpsertMediaReplica(ctx context.Context, arg UpsertMediaReplicaParams) (MediaReplica, error) {
	row := q.db.QueryRow(ctx, upsertMediaReplica,
		arg.ObjectID,
		arg.ProviderID,
		arg.Status,
		arg.Error,
	)
	var i MediaReplica
	err := row.Scan(
		&i.ObjectID,
		&i.ProviderID,
		&i.Status,
		&i.Error,
		&i.ReplicatedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
